// Generated by Cypress Author on 2026-10-02.
import { mountWorkspace, mockRefresh, task } from "../../support/tasks";

describe("Edit tasks", () => {
  beforeEach(() => {
    mountWorkspace([task()]);
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-title").should("have.value", "Buy groceries");
    cy.get("#task-description").should("have.value", "Milk and bread");
  });

  it("edits a task → saves both fields and refreshes the existing row", () => {
    const updated = task({ title: "Order groceries", description: "Deliver tomorrow" });
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: updated }).as("updateTask");
    mockRefresh([updated]);
    cy.get("#task-title").clear().type(updated.title);
    cy.get("#task-description").clear().type(updated.description);
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask").its("request.body").should("deep.equal", {
      title: updated.title, description: updated.description,
    });
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
    cy.get('[role="status"]').should("have.text", "Task updated.");
    cy.get('section[aria-label="Task list"] li').should("have.length", 1)
      .and("contain.text", updated.title).and("contain.text", updated.description)
      .and("not.contain.text", "Buy groceries");
    cy.get("@updateTask.all").should("have.length", 1);
  });

  it("fails to save → keeps the original row and entered edits for retry", () => {
    cy.intercept("PUT", "/api/tasks/42", {
      statusCode: 500, body: { message: "Unable to update task." },
    }).as("updateTask");
    cy.get("#task-title").clear().type("Order groceries");
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask");
    cy.get('dialog [role="alert"]').should("have.text", "Unable to update task.");
    cy.get("#task-title").should("have.value", "Order groceries").and("not.be.disabled");
    cy.contains("dialog button", "Save changes").should("be.enabled");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries");
    cy.get('[role="status"]').should("not.exist");
  });

  it("cancels edits → keeps the task unchanged without saving", () => {
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: task() }).as("updateTask");
    cy.get("#task-title").clear().type("Discard this edit");
    cy.contains("dialog button", "Cancel").click();
    cy.get("dialog").should("not.exist");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries")
      .and("not.contain.text", "Discard this edit");
    cy.get('[aria-label="Edit Buy groceries"]').should("be.focused");
    cy.get("@updateTask.all").should("have.length", 0);
  });
});

// Generated by Cypress Author on 2026-10-02.
describe("Edit optional task fields", () => {
  const original = task({ priority: 1, dueDate: "2026-11-12" });

  beforeEach(() => {
    mountWorkspace([original]);
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-priority").should("have.value", "1");
    cy.get("#task-due-date").should("have.value", original.dueDate);
  });

  it("changes priority and due date → refreshes the task and reopens saved values", () => {
    const updated = task({ priority: 4, dueDate: "2026-12-01" });
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: updated }).as("updateTask");
    mockRefresh([updated]);
    cy.get("#task-priority").select("4");
    cy.get("#task-due-date").clear().type(updated.dueDate!);
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask").its("request.body").should("deep.equal", {
      title: updated.title, description: updated.description, priority: 4, dueDate: updated.dueDate,
    });
    cy.wait("@refreshTasks");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Priority 4").and("contain.text", "Due 2026-12-01");
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-priority").should("have.value", "4");
    cy.get("#task-due-date").should("have.value", updated.dueDate);
  });

  it("clears the due date and resets priority → saves an unscheduled task with priority 3", () => {
    const updated = task();
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: updated }).as("updateTask");
    mockRefresh([updated]);
    cy.get("#task-priority").select("3");
    cy.get("#task-due-date").clear();
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask").its("request.body").should("deep.equal", {
      title: updated.title, description: updated.description, dueDate: null,
    });
    cy.wait("@refreshTasks");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Priority 3").and("not.contain.text", "Due");
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-priority").should("have.value", "3");
    cy.get("#task-due-date").should("have.value", "");
  });

  it("edits only the title → keeps existing optional values", () => {
    const updated = { ...original, title: "Order groceries" };
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: updated }).as("updateTask");
    mockRefresh([updated]);
    cy.get("#task-title").clear().type(updated.title);
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask").its("request.body").should("deep.equal", {
      title: updated.title, description: updated.description, priority: 1, dueDate: original.dueDate,
    });
    cy.wait("@refreshTasks");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Priority 1").and("contain.text", "Due 2026-11-12");
  });

  it("fails to save optional changes → keeps values for retry and the original task unchanged", () => {
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 500, body: { message: "Unable to update task." } }).as("updateTask");
    cy.get("#task-priority").select("2");
    cy.get("#task-due-date").clear().type("2026-12-01");
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask");
    cy.get('dialog [role="alert"]').should("have.text", "Unable to update task.");
    cy.get("#task-priority").should("have.value", "2").and("not.be.disabled");
    cy.get("#task-due-date").should("have.value", "2026-12-01").and("not.be.disabled");
    cy.contains("dialog button", "Cancel").click();
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Priority 1").and("contain.text", "Due 2026-11-12");
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-priority").should("have.value", "1");
    cy.get("#task-due-date").should("have.value", original.dueDate);
  });
});
